queries.sparql:
SELECT ?person ?organisation
WHERE {
  ?p v:speaks_at <https://newsroom.sgit.ai/portugal/id/event:startup-summit-lisbon-2026> ;
     rdfs:label ?person ;
     v:listed_under ?o .
  ?o rdfs:label ?organisation .
}
ORDER BY ?person

SELECT ?stage (GROUP_CONCAT(?s; separator=" · ") AS ?sessions)
WHERE {
  ?sess v:on_stage ?st ; rdfs:label ?s .
  ?st rdfs:label ?stage . FILTER(lang(?stage) = "en")
}
GROUP BY ?stage

SELECT ?publisher ?title ?published
WHERE {
  ?c a t:Coverage ; v:covers <https://newsroom.sgit.ai/portugal/id/event:startup-summit-lisbon-2026> ; rdfs:label ?title .
  ?c v:published_by ?org . ?org rdfs:label ?publisher .
  OPTIONAL { ?c a:published ?published }
}
ORDER BY ?published ?publisher

SELECT ?person ?source
WHERE {
  ?p a t:Person ; a:no_longer_listed true ; rdfs:label ?person ; a:source ?source .
}
